INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Colombia', 'colombia', 'AMERICA', 'Colombia es el mayor productor mundial de arábica lavado, cultivado en las tres cordilleras de los Andes por cientos de miles de pequeños caficultores. La diversidad de microclimas entre los 1.200 y los 2.200 metros permite perfiles que van de lo dulce y equilibrado a lo intensamente frutal. La Federación Nacional de Cafeteros y una larga tradición de beneficio húmedo han convertido al país en sinónimo de taza limpia y consistente.', 4.5709, -74.2973, 1200, 2200, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Etiopía', 'etiopia', 'AFRICA', 'Etiopía es la cuna botánica del café Arábica, donde el cafeto crece de forma silvestre en los bosques montañosos del suroeste. Miles de variedades heredadas (heirloom), nunca clasificadas varietalmente como en otros países, generan una diversidad genética y sensorial inigualable, con tazas florales y afrutadas en los lavados y notas a fruta madura en los naturales. El café sigue siendo, además, el eje social y ritual del país a través de la ceremonia tradicional del buna.', 9.145, 40.4897, 1500, 2200, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Kenia', 'kenia', 'AFRICA', 'Kenia perfeccionó el café lavado hasta convertirlo en referencia mundial gracias a las variedades locales SL28 y SL34, seleccionadas en los años treinta por su resistencia a la sequía y su extraordinaria calidad en taza. El sistema de subasta semanal y las estaciones de lavado cooperativas en las laderas rojas volcánicas de Nyeri y Kirinyaga producen tazas de acidez cítrica intensa y notas a grosella negra que son la firma sensorial del país.', -0.0236, 37.9062, 1500, 2100, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Brasil', 'brasil', 'AMERICA', 'Brasil es el mayor productor mundial de café y el único gran origen donde el relieve permite mecanizar la cosecha en grandes fazendas. El proceso natural y el descascarillado honey predominan sobre el lavado, generando tazas de baja acidez, cuerpo untuoso y dulzor a chocolate y frutos secos. Regiones como el Sul de Minas y el Cerrado Mineiro concentran la producción de especialidad del país.', -14.235, -51.9253, 800, 1400, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Guatemala', 'guatemala', 'AMERICA', 'Guatemala cultiva café bajo sombra en suelos volcánicos a lo largo de ocho regiones reconocidas por Anacafé, cada una con un microclima propio. Antigua es célebre por su dulzor especiado y su característica nota ligeramente ahumada de origen volcánico, mientras que Huehuetenango, protegida de las heladas por los vientos cálidos del istmo de Tehuantepec, alcanza altitudes excepcionales que producen tazas florales de gran acidez.', 15.7835, -90.2308, 1300, 2000, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Costa Rica', 'costa-rica', 'AMERICA', 'Costa Rica, que prohibió por ley el cultivo de robusta, ha construido su identidad especializándose exclusivamente en arábica de altura procesado en micro-beneficios propios de cada finca. El país fue pionero mundial del proceso honey, y regiones como Tarrazú, en las montañas de Los Santos, producen tazas brillantes, dulces y de gran limpieza.', 9.7489, -83.7534, 1200, 1900, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Panamá', 'panama', 'AMERICA', 'Panamá, y en particular la región volcánica de Boquete a los pies del Barú, se convirtió en epicentro mundial de la variedad Geisha tras su irrupción en las subastas Best of Panama a comienzos de siglo. La combinación de altitud, suelos volcánicos jóvenes y microclimas frescos produce tazas de una complejidad floral y aromática que han redefinido el techo de calidad del café de especialidad.', 8.538, -80.7821, 1200, 2000, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Ruanda', 'ruanda', 'AFRICA', 'Ruanda, el país de las mil colinas, reconstruyó su industria cafetera tras 1994 apoyándose en miles de pequeños productores organizados en estaciones de lavado cooperativas. Cultivado sobre todo con la variedad Bourbon Rojo en las laderas que rodean el lago Kivu y las tierras altas del sur, su café lavado destaca por un dulzor a fruta roja y una acidez cítrica elegante.', -1.9403, 29.8739, 1400, 2000, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Perú', 'peru', 'AMERICA', 'Perú cultiva café mayoritariamente orgánico en pequeñas parcelas familiares repartidas por la ceja de selva andina, desde Cajamarca en el norte hasta Cusco en el sur. La combinación de altitud, sombra natural y variedades tradicionales como Typica y Bourbon produce tazas suaves, dulces y de acidez moderada que han ganado terreno constante en el mercado de especialidad.', -9.19, -75.0152, 1200, 2000, now(), now());
INSERT INTO countries (id, name, slug, continent, description, latitude, longitude, typical_altitude_min_m, typical_altitude_max_m, created_at, updated_at) VALUES (gen_random_uuid(), 'Indonesia', 'indonesia', 'ASIA', 'Indonesia, y en particular las islas de Sumatra y Sulawesi, desarrolló un método de proceso propio, el giling basah o trillado húmedo, que reduce la acidez y potencia un cuerpo denso y notas terrosas y especiadas únicas en el mundo del café. Los cafetales, cultivados a la sombra en suelos volcánicos entre los 1.000 y los 1.700 metros, son trabajados por miles de pequeños agricultores organizados en cooperativas.', -0.7893, 113.9213, 1000, 1700, now(), now());
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Huila', 'huila', 'Huila, en el macizo colombiano, es el departamento con mayor producción de café de especialidad del país, con fincas entre los 1.400 y los 2.100 metros que aportan dulzor a panela y acidez cítrica equilibrada.', 2.5359, -75.5277, now(), now() FROM countries WHERE slug = 'colombia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Nariño', 'narino', 'Nariño, en el extremo suroeste junto a la frontera con Ecuador, cultiva café en algunas de las altitudes más extremas del país, entre los 1.700 y los 2.300 metros, lo que produce tazas de acidez brillante y notas florales y frutales.', 1.2136, -77.2811, now(), now() FROM countries WHERE slug = 'colombia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cauca', 'cauca', 'Cauca combina suelos volcánicos y una topografía escarpada entre los 1.500 y los 2.100 metros, con una fuerte tradición de fincas indígenas y campesinas que han apostado por procesos experimentales.', 2.4448, -76.6147, now(), now() FROM countries WHERE slug = 'colombia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Yirgacheffe', 'yirgacheffe', 'Yirgacheffe, en la zona de Gedeo, es la denominación etíope más reconocida internacionalmente por sus tazas lavadas de intensa floralidad, cultivadas entre los 1.800 y los 2.200 metros sobre suelos ricos en materia orgánica.', 6.1667, 38.2039, now(), now() FROM countries WHERE slug = 'etiopia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Sidama', 'sidama', 'Sidama (antes Sidamo), al sur del lago Awasa, es una de las mayores zonas cafeteras de Etiopía, con jardines familiares mixtos que combinan café, enset y árboles de sombra nativos entre los 1.700 y los 2.100 metros.', 7.05, 38.4955, now(), now() FROM countries WHERE slug = 'etiopia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Guji', 'guji', 'Guji, en el sur de la región de Oromía, es una de las zonas cafeteras más jóvenes en reconocimiento internacional, con altitudes que superan los 2.000 metros y tazas naturales de perfil intensamente afrutado.', 5.75, 38.9, now(), now() FROM countries WHERE slug = 'etiopia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Nyeri', 'nyeri', 'Nyeri, a los pies del monte Kenia, concentra algunas de las estaciones de lavado más premiadas del país sobre suelos rojos volcánicos ricos en nitrógeno, entre los 1.600 y los 2.000 metros.', -0.4167, 36.95, now(), now() FROM countries WHERE slug = 'kenia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Kirinyaga', 'kirinyaga', 'Kirinyaga, en la ladera sureste del monte Kenia, comparte los suelos volcánicos y la altitud de Nyeri y es reconocida por lotes de gran complejidad ácida y cuerpo firme.', -0.5, 37.2833, now(), now() FROM countries WHERE slug = 'kenia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Sul de Minas', 'sul-de-minas', 'El Sul de Minas, alrededor de Varginha, es la mayor región cafetera de Brasil, con fincas entre los 900 y los 1.300 metros dedicadas principalmente al proceso natural y honey a gran escala.', -21.5533, -45.43, now(), now() FROM countries WHERE slug = 'brasil';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cerrado Mineiro', 'cerrado-mineiro', 'Cerrado Mineiro, en torno a Patrocínio, fue la primera región brasileña en obtener denominación de origen para café gracias a su clima estable, con estación seca definida ideal para el secado natural.', -18.9439, -46.9925, now(), now() FROM countries WHERE slug = 'brasil';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Antigua', 'antigua', 'Antigua, rodeada por los volcanes Agua, Fuego y Acatenango, cultiva café en suelos de ceniza volcánica entre los 1.500 y los 1.700 metros, produciendo tazas dulces con la característica nota ligeramente ahumada de la región.', 14.5586, -90.7295, now(), now() FROM countries WHERE slug = 'guatemala';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Huehuetenango', 'huehuetenango', 'Huehuetenango, en el altiplano occidental fronterizo con México, es la región de mayor altitud de Guatemala; los vientos cálidos del istmo de Tehuantepec la protegen de heladas y permiten cultivar café hasta los 2.000 metros.', 15.3197, -91.4711, now(), now() FROM countries WHERE slug = 'guatemala';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Tarrazú', 'tarrazu', 'Tarrazú, en la cordillera de Los Santos al sur del Valle Central, es la región más reconocida de Costa Rica por sus suelos volcánicos jóvenes y su altitud, que supera los 1.700 metros en varias fincas.', 9.65, -84.0167, now(), now() FROM countries WHERE slug = 'costa-rica';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Tres Ríos', 'tres-rios', 'Tres Ríos, en el Valle Central junto al volcán Irazú, fue históricamente la primera región costarricense en ganar prestigio internacional gracias a sus suelos fértiles y su clima estable.', 9.9167, -83.9667, now(), now() FROM countries WHERE slug = 'costa-rica';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Boquete', 'boquete', 'Boquete, a los pies del volcán Barú, ofrece el clima fresco y nuboso y los suelos volcánicos que convirtieron a la región en el epicentro mundial de la variedad Geisha.', 8.7833, -82.4333, now(), now() FROM countries WHERE slug = 'panama';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Volcán', 'volcan', 'Volcán, en la vertiente oeste del Barú hacia la frontera con Costa Rica, comparte la altitud y los suelos volcánicos de Boquete con un perfil de producción más orientado a variedades tradicionales.', 8.7667, -82.6333, now(), now() FROM countries WHERE slug = 'panama';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Nyamasheke', 'nyamasheke', 'Nyamasheke, sobre la ribera oriental del lago Kivu, es una de las regiones cafeteras más antiguas de Ruanda, con laderas empinadas cultivadas casi en su totalidad por pequeños productores de menos de media hectárea.', -2.3667, 29.1167, now(), now() FROM countries WHERE slug = 'ruanda';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Huye', 'huye', 'Huye, en la antigua provincia de Butare al sur del país, es cuna del renacimiento cafetero ruandés de comercio directo iniciado a comienzos de los años 2000.', -2.5967, 29.7392, now(), now() FROM countries WHERE slug = 'ruanda';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cajamarca', 'cajamarca', 'La zona cafetera del departamento de Cajamarca, concentrada en las provincias norteñas de San Ignacio y Jaén, produce café de sombra mayormente orgánico entre los 1.200 y los 1.900 metros.', -5.1444, -79.0072, now(), now() FROM countries WHERE slug = 'peru';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cusco', 'cusco', 'La Convención, en la selva alta de Cusco alrededor de Quillabamba, cultiva café bajo sombra en laderas escarpadas entre los 1.200 y los 1.800 metros, con una fuerte tradición cooperativa.', -12.8667, -72.6833, now(), now() FROM countries WHERE slug = 'peru';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Aceh (Gayo)', 'aceh', 'Las tierras altas de Gayo, alrededor de Takengon en el norte de Sumatra, cultivan café entre los 1.200 y los 1.700 metros y son la mayor zona de café orgánico certificado de Asia.', 4.6167, 96.8333, now(), now() FROM countries WHERE slug = 'indonesia';
INSERT INTO regions (id, country_id, name, slug, description, latitude, longitude, created_at, updated_at) SELECT gen_random_uuid(), id, 'Toraja', 'toraja', 'Toraja, en las montañas centrales de Sulawesi, cultiva café en terrazas escarpadas entre los 1.200 y los 1.800 metros, con una cultura agrícola profundamente ligada a las tradiciones ancestrales torajanas.', -2.97, 119.8975, now(), now() FROM countries WHERE slug = 'indonesia';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca La Esperanza', 'finca-la-esperanza', 'Finca familiar de tercera generación en las laderas de Pitalito dedicada al beneficio húmedo tradicional y la selección manual de cerezas maduras.', now(), now() FROM regions WHERE slug = 'huila';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Norte del Huila', 'cooperativa-norte-del-huila', 'Cooperativa que agrupa a más de doscientas familias caficultoras del norte del departamento y centraliza el proceso de lavado y secado en patios comunitarios.', now(), now() FROM regions WHERE slug = 'huila';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca El Mirador', 'finca-el-mirador', 'Finca de altura en el municipio de Buesaco que aprovecha el clima frío y volcánico de Nariño para lotes lavados de perfil marcadamente floral.', now(), now() FROM regions WHERE slug = 'narino';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Asociación de Productores de Nariño', 'asociacion-de-productores-de-narino', 'Asociación de pequeños productores del altiplano de Túquerres enfocada en la trazabilidad y la mejora continua de la calidad en taza.', now(), now() FROM regions WHERE slug = 'narino';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca Buenos Aires', 'finca-buenos-aires', 'Finca en el municipio de Inzá pionera en la región en el uso de fermentaciones anaeróbicas controladas para lotes de microlote.', now(), now() FROM regions WHERE slug = 'cauca';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Cauca Sostenible', 'cooperativa-cauca-sostenible', 'Cooperativa que certifica prácticas agroecológicas entre productores del macizo caucano y comercializa cafés lavados de perfil dulce.', now(), now() FROM regions WHERE slug = 'cauca';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Estación de Lavado Konga', 'estacion-de-lavado-konga', 'Estación de lavado comunitaria en Gedeb que procesa cerezas de cientos de pequeños huertos familiares de menos de una hectárea cada uno.', now(), now() FROM regions WHERE slug = 'yirgacheffe';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Gedeb', 'cooperativa-gedeb', 'Cooperativa de segundo nivel que agrupa a varias estaciones de lavado del distrito de Gedeb bajo estándares comunes de calidad.', now(), now() FROM regions WHERE slug = 'yirgacheffe';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Bensa', 'cooperativa-bensa', 'Cooperativa del distrito de Bensa que procesa cerezas mediante secado natural en camas africanas elevadas.', now(), now() FROM regions WHERE slug = 'sidama';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Unión Sidama', 'union-sidama', 'Unión de cooperativas de la región de Sidama que exporta cafés certificados bajo comercio directo desde hace más de dos décadas.', now(), now() FROM regions WHERE slug = 'sidama';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Hambela', 'cooperativa-hambela', 'Cooperativa de la localidad de Hambela Wamena que trabaja con variedades heirloom silvestres recolectadas en bosques semi nativos.', now(), now() FROM regions WHERE slug = 'guji';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca Uraga', 'finca-uraga', 'Finca familiar en el distrito de Uraga especializada en el secado lento de cerezas seleccionadas sobre camas elevadas de bambú.', now(), now() FROM regions WHERE slug = 'guji';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Tekangu', 'cooperativa-tekangu', 'Sociedad cooperativa de agricultores (FCS) que opera una estación de lavado propia y beneficia café de más de mil pequeños socios de Nyeri.', now(), now() FROM regions WHERE slug = 'nyeri';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Estación Gikanda', 'estacion-gikanda', 'Estación de lavado histórica de Nyeri conocida por sus lotes de acidez cítrica intensa y perfil a grosella negra.', now(), now() FROM regions WHERE slug = 'nyeri';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Kiangoi', 'cooperativa-kiangoi', 'Cooperativa de Kirinyaga cuya estación de lavado Kiangoi ha obtenido puntuaciones consistentemente altas en las subastas nacionales.', now(), now() FROM regions WHERE slug = 'kirinyaga';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Estación Ndima', 'estacion-ndima', 'Estación de beneficio húmedo comunitaria situada sobre las laderas orientales del monte Kenia.', now(), now() FROM regions WHERE slug = 'kirinyaga';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Fazenda Santa Inês', 'fazenda-santa-ines', 'Fazenda familiar de cuarta generación cerca de Varginha especializada en secado natural en terrazas de cemento.', now(), now() FROM regions WHERE slug = 'sul-de-minas';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Fazenda Boa Vista', 'fazenda-boa-vista', 'Fazenda de tamaño medio pionera en la región en el proceso honey mediante despulpado parcial y secado en camas africanas.', now(), now() FROM regions WHERE slug = 'sul-de-minas';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Fazenda Cachoeira', 'fazenda-cachoeira', 'Fazenda mecanizada del altiplano de Patrocínio que combina irrigación por goteo y selección óptica para lotes naturales homogéneos.', now(), now() FROM regions WHERE slug = 'cerrado-mineiro';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Cooperativa Cerrado Mineiro', 'cooperativa-cerrado-mineiro', 'Cooperativa regional que agrupa a productores del Cerrado bajo el sello de denominación de origen Cerrado Mineiro.', now(), now() FROM regions WHERE slug = 'cerrado-mineiro';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca San José', 'finca-san-jose', 'Finca histórica a las faldas del volcán de Agua que mantiene sombra de inga y procesa café lavado desde finales del siglo XIX.', now(), now() FROM regions WHERE slug = 'antigua';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca Los Volcanes', 'finca-los-volcanes', 'Finca familiar entre los volcanes de Fuego y Acatenango dedicada al cultivo de Bourbon y Caturra bajo sombra.', now(), now() FROM regions WHERE slug = 'antigua';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca La Soledad', 'finca-la-soledad', 'Finca de altura en las montañas de los Cuchumatanes que cultiva Typica tradicional bajo un régimen de lluvias particularmente marcado.', now(), now() FROM regions WHERE slug = 'huehuetenango';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca Chiantla', 'finca-chiantla', 'Finca familiar del municipio de Chiantla que combina café de altura con cultivos de subsistencia en pequeñas parcelas en ladera.', now(), now() FROM regions WHERE slug = 'huehuetenango';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Microbeneficio Don Mayo', 'microbeneficio-don-mayo', 'Microbeneficio familiar de San Marcos de Tarrazú especializado en procesos honey con control preciso de mucílago residual.', now(), now() FROM regions WHERE slug = 'tarrazu';
INSERT INTO producers (id, region_id, name, slug, description, created_at, updated_at) SELECT gen_random_uuid(), id, 'Finca La Candelilla', 'finca-la-candelilla', 'Finca de altura pionera en Tarrazú en fermentaciones anaeróbicas experimentales de pequeño lote.', now(), now() FROM regions WHERE slug = 'tarrazu';
