INSERT INTO coffee_lots (id, farm_id, code, harvest_date, roast_date, quantity_kg, supplier, created_at) SELECT gen_random_uuid(), id, 'COL-HUI-001-2025-10', '2025-10-15', '2026-08-25', 307, 'Exportadora Colombia', now() FROM farms WHERE slug = 'finca-la-esperanza-finca';
INSERT INTO products (id, sku, name, slug, short_description, long_description, country_id, region_id, producer_id, farm_id, current_lot_id, variety, process, altitude_m, roast_level, acidity, body, sweetness, status, base_price_cents, created_at, updated_at) SELECT gen_random_uuid(), 'COL-HUI-001', 'Colombia Huila — Finca La Esperanza', 'colombia-huila-finca-la-esperanza', 'Un lavado clásico de Huila con dulzor a panela y un toque cítrico que representa la taza colombiana en su máxima expresión de equilibrio.', 'Cultivado a 1.750 metros en las laderas de Pitalito por la familia de Finca La Esperanza, este café Caturra se beneficia mediante lavado tradicional y secado lento al sol. La altitud y los suelos volcánicos de Huila aportan una dulzura natural a panela y manzana roja, mientras que el proceso lavado realza una acidez cítrica limpia y bien integrada. Una taza equilibrada y versátil, fiel al estilo que hizo mundialmente reconocido al café colombiano.', (SELECT id FROM countries WHERE slug = 'colombia'), (SELECT id FROM regions WHERE slug = 'huila'), (SELECT id FROM producers WHERE slug = 'finca-la-esperanza'), (SELECT id FROM farms WHERE slug = 'finca-la-esperanza-finca'), (SELECT id FROM coffee_lots WHERE code = 'COL-HUI-001-2025-10'), 'Caturra', 'WASHED', 1750, 'LIGHT', 4, 3, 4, 'ACTIVE', 1250, now(), now();
