INSERT INTO products (id, sku, name, slug, short_description, long_description, country_id, region_id, producer_id, farm_id, current_lot_id, variety, process, altitude_m, roast_level, acidity, body, sweetness, status, base_price_cents, created_at, updated_at) SELECT gen_random_uuid(), 'ETI-SID-001', 'Etiopía Sidama — Cooperativa Bensa Natural', 'etiopia-sidama-cooperativa-bensa', 'Un natural etíope de dulzor intenso, con fresa, arándano y notas a chocolate blanco.', 'La Cooperativa Bensa seca sus cerezas enteras sobre camas africanas elevadas durante hasta tres semanas, dejando que el fruto transmita todo su azúcar al grano. El resultado es un café de variedades heirloom cultivado sobre los 1.900 metros con una taza intensamente dulce, donde conviven la fresa, el arándano y sutiles notas florales y a chocolate blanco. Un natural etíope de manual, limpio pese a su carga frutal.', (SELECT id FROM countries WHERE slug = 'etiopia'), (SELECT id FROM regions WHERE slug = 'sidama'), (SELECT id FROM producers WHERE slug = 'cooperativa-bensa'), (SELECT id FROM farms WHERE slug = 'cooperativa-bensa-finca'), (SELECT id FROM coffee_lots WHERE code = 'ETI-SID-001-2025-11'), 'Heirloom', 'NATURAL', 1900, 'LIGHT', 4, 3, 5, 'ACTIVE', 1500, now(), now();
