INSERT INTO products (id, sku, name, slug, short_description, long_description, country_id, region_id, producer_id, farm_id, current_lot_id, variety, process, altitude_m, roast_level, acidity, body, sweetness, status, base_price_cents, created_at, updated_at) SELECT gen_random_uuid(), 'IDN-ACE-002', 'Indonesia Gayo — Estación Takengon Natural', 'indonesia-gayo-estacion-takengon', 'Un natural experimental de Gayo que suma frutos rojos y chocolate al característico cuerpo sumatrano.', 'Junto al lago Laut Tawar, la Estación Takengon seca cerezas de Bourbon con la fruta entera, un proceso natural poco habitual en Sumatra, tradicionalmente dominada por el trillado húmedo. El resultado es una taza de cuerpo denso con notas a frutos rojos, chocolate y especias, que conserva la untuosidad típica de la región sin renunciar a una mayor complejidad frutal. Un lote experimental de volumen reducido.', (SELECT id FROM countries WHERE slug = 'indonesia'), (SELECT id FROM regions WHERE slug = 'aceh'), (SELECT id FROM producers WHERE slug = 'estacion-takengon'), (SELECT id FROM farms WHERE slug = 'estacion-takengon-finca'), (SELECT id FROM coffee_lots WHERE code = 'IDN-ACE-002-2026-01'), 'Bourbon', 'NATURAL', 1550, 'MEDIUM', 3, 4, 4, 'ACTIVE', 1450, now(), now();
