INSERT INTO coffee_lots (id, farm_id, code, harvest_date, roast_date, quantity_kg, supplier, created_at) SELECT gen_random_uuid(), id, 'IDN-TOR-001-2026-01', '2026-01-12', '2026-08-16', 344, 'Exportadora Indonesia', now() FROM farms WHERE slug = 'koperasi-toraja-melo-finca';
INSERT INTO products (id, sku, name, slug, short_description, long_description, country_id, region_id, producer_id, farm_id, current_lot_id, variety, process, altitude_m, roast_level, acidity, body, sweetness, status, base_price_cents, created_at, updated_at) SELECT gen_random_uuid(), 'IDN-TOR-001', 'Indonesia Toraja — Koperasi Toraja Melo', 'indonesia-toraja-koperasi-toraja-melo', 'El perfil terroso y especiado de Sulawesi, con chocolate amargo y notas a cedro.', 'En la meseta de Tana Toraja, la cooperativa Toraja Melo procesa Typica tradicional mediante trillado húmedo sobre patios de secado escalonado, siguiendo prácticas agrícolas ligadas a la cultura ancestral torajana. Cultivado a 1.500 metros, este café desarrolla un cuerpo denso y una taza de notas especiadas, terrosas, con chocolate amargo y un cierre a cedro. Una experiencia sensorial radicalmente distinta a la de los orígenes americanos o africanos.', (SELECT id FROM countries WHERE slug = 'indonesia'), (SELECT id FROM regions WHERE slug = 'toraja'), (SELECT id FROM producers WHERE slug = 'koperasi-toraja-melo'), (SELECT id FROM farms WHERE slug = 'koperasi-toraja-melo-finca'), (SELECT id FROM coffee_lots WHERE code = 'IDN-TOR-001-2026-01'), 'Typica', 'WASHED', 1500, 'MEDIUM_DARK', 2, 5, 3, 'ACTIVE', 1400, now(), now();
